import{_ as a,a as s,c as t,j as r}from"./chunks/framework.DVzkjf-b.js";const i="/images/editorial/field-desk.jpg",m=JSON.parse('{"title":"Writing","description":"Keith Williams’s classroom field notes, working papers, and reporting on AI and software engineering careers.","frontmatter":{"title":"Writing","description":"Keith Williams’s classroom field notes, working papers, and reporting on AI and software engineering careers."},"headers":[],"relativePath":"writing.md","filePath":"writing.md"}'),o={name:"writing.md"};function n(h,e,l,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="writing" tabindex="-1">Writing <a class="header-anchor" href="#writing" aria-label="Permalink to &quot;Writing&quot;">​</a></h1><figure><img src="'+i+'" alt="A blue workbench with an open notebook and a red pencil in angled sunlight." width="1440" height="960" decoding="async"><figcaption>AI-generated editorial illustration.</figcaption></figure><h2 id="from-the-classroom" tabindex="-1">From the classroom <a class="header-anchor" href="#from-the-classroom" aria-label="Permalink to &quot;From the classroom&quot;">​</a></h2><h3 id="the-tests-passed-who-won-the-game" tabindex="-1"><a href="/teaching/when-ai-helps-write-the-code">The Tests Passed. Who Won the Game?</a> <a class="header-anchor" href="#the-tests-passed-who-won-the-game" aria-label="Permalink to &quot;[The Tests Passed. Who Won the Game?](/teaching/when-ai-helps-write-the-code)&quot;">​</a></h3><p><em>Classroom field note · November 2026</em></p><p>A Rock, Paper, Scissors project raises an awkward question for the person running the demo. Passing tests can tell you what the program did. Who decided what it was supposed to do? I use examples from three NJIT courses to show where an AI coach can help and when a student needs the next turn.</p><p><a href="/downloads/AI-Studio-Starter.zip">Download the Studio starter for teachers (.zip)</a></p><p><a href="/teaching/studio-field-notes">Read the Studio field notes</a> for the research behind the coaching prompts and the questions I still have about learning.</p><h2 id="research-essays" tabindex="-1">Research essays <a class="header-anchor" href="#research-essays" aria-label="Permalink to &quot;Research essays&quot;">​</a></h2><p>These working papers trace questions I’m investigating through software I’ve built and systems I’m still designing.</p><ul><li><a href="/research/systems/english-software-engineering">English as a software engineering abstraction</a> explores what happens when a written instruction becomes a specification another person or an AI can test.</li><li><a href="/research/systems/provenance-knowledge-graphs">Building qualified knowledge from contradictory sources</a> follows a claim back to its evidence and asks what to keep when two sources disagree.</li><li><a href="/research/systems/human-attention-kanban">Human attention as an engineering constraint</a> asks which decisions are worth putting in front of a human reviewer.</li></ul><p><a href="/research/systems/">Browse the research series</a></p><h2 id="career-field-notes" tabindex="-1">Career field notes <a class="header-anchor" href="#career-field-notes" aria-label="Permalink to &quot;Career field notes&quot;">​</a></h2><h3 id="what-are-ai-employers-asking-engineers-to-do" tabindex="-1"><a href="/ai-careers">What are AI employers asking engineers to do?</a> <a class="header-anchor" href="#what-are-ai-employers-asking-engineers-to-do" aria-label="Permalink to &quot;[What are AI employers asking engineers to do?](/ai-careers)&quot;">​</a></h3><p>I read 50 job descriptions across five role families. The report links to the postings, separates internships from experienced roles, and gives students a way to choose what to practice for their portfolio.</p>',15)])])}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
